# -*- coding: utf-8 -*-
import json, os, sys
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from ai_trader.journal import Journal
L = json.loads(r'''["=== 一、怎么找到的 ===","","本轮先做了一件以前没做过的事：量真实覆盖率。","本地没有 coverage 包，自己用 sys.settrace 写了一个。","","全量 487 个测试跑下来，ai_trader/ 合计 68.1% 行覆盖。分文件看：","","    trading/engine.py      82%   核心决策","    trading/trend.py       81%   策略","    exchange/spot.py       91%   下单","    exchange/live.py       85%   下单","    guard.py / risk.py     86%   风控","    trading/features.py     1%   <- 只有 73/74 行没跑过","","features.py 覆盖 1% 很刺眼。顺着查：它只被 engine._step 里那段剥头皮分支调用，","而 _step 里 485-550 行整段（strategy != trend 的分支）一行都没被执行过。","也就是说：剥头皮策略在生产里是死代码。这本身合理——它被回测否决了，只留作对照。","","但「一行都不跑的分支」意味着：这条分支里的一切错误都测不出来。","所以我接着问了一个更要紧的问题：如果 AI_STRATEGY 的值不是 trend，会发生什么？","","=== 二、查出来的洞 ===","","config.py 原来是这样读的：","    cfg.trading.strategy = os.environ.get(\"AI_STRATEGY\", cfg.trading.strategy)","","os.environ.get 的第二个参数只在变量未定义时生效。","变量被设成空串或拼错，默认值根本不参与，错值直接流进业务逻辑。实测：","","    AI_STRATEGY=trend      -> trend     -> 趋势（正确）","    AI_STRATEGY=' Trend '  -> ' Trend ' -> 剥头皮","    AI_STRATEGY=TREND      -> TREND     -> 剥头皮","    AI_STRATEGY=Trand      -> Trand     -> 剥头皮","    AI_STRATEGY=''         -> ''        -> 剥头皮","    AI_STRATEGY='trend '   -> 'trend '  -> 剥头皮","","engine.py:480 的判断是 if self.tcfg.strategy == \"trend\":，","所以上面五种全部掉进剥头皮路径，而那条路径会正常下单、正常记日志、正常出决策","——服务活着、日志干净、策略错了。","","同一个洞还有第二个入口：","    cfg.trading.exec_market = os.environ.get(\"AI_EXEC_MARKET\", ...)","main.py:73 用 if cfg.trading.exec_market == \"spot\": 决定挂哪个执行器。","所以 AI_EXEC_MARKET=Spot（大写 S）会去建永续执行器","——而第 97/98 轮刚证明永续在 100U 上 1x 的生死线是 77.9U，回撤 22% 就永久开不出仓。","","=== 三、为什么这不是假想 ===","","1) 服务器上已经存在 AI_FEISHU_WEBHOOK=（空值）这种写法，留空值是这个部署的常态；","2) config.py 里 strategy 那段注释自己就写着「这已经坑过一次：日志里同时存在 scalp 和 trend","   的记录，原因是手动执行读不到 systemd 的 EnvironmentFile」。","","同一个坑踩过一次，但那次只把默认值从 scalp 改成 trend，没有堵住拼错/空值这条路。","","=== 四、改法 ===","","加一个 _pick(env, default, allowed)：","- 空值/纯空白 -> 用默认值，并打 warning；","- 其余不认识的值 -> ValueError，拒绝启动。","","大小写和首尾空白自动归一，所以 ' Trend ' 这类事故从源头消失。","显式的 scalp / perp 仍然允许——回测否决的是「拿它当默认」，不是「不许跑」。","","=== 五、顺带被自己的测试咬了一口 ===","","改完跑全量，test_deploy_env_completeness.py 红了。","它靠正则扫 os.environ.get(\"AI_XXX\") 的字面量，来保证「代码读的变量，部署模板都写了」。","我把读取改成 _pick(\"AI_XXX\", ...) 之后，os.environ.get(env) 里的 env 是变量，扫不到了。","","这条测试红得完全正确——它正好说明这个不变量在起作用。","正确的处理是让扫描器认识新的读取形式（加一条 _pick( 的正则），而不是放宽断言。","加完扫到 15 个变量，比之前多了 AI_EXEC_MARKET，","并且 install_server.sh 和 env.server.example 两个模板都覆盖了。","","=== 六、验证 ===","","新增 tests/test_config_enum_guard.py（7 条）；","5 条变异全部变红，包括把原来的 os.environ.get 原样放回去（7 条全红）。","全量 494 全绿（487 -> 494）。","","其他变异：去掉拼错校验、不做大小写归一、空值不回落默认、空值回落到 scalp——全部红。","","=== 七、副产物：覆盖率工具 ===","","tools/cov.py + tests/conftest.py（AI_COV=1 才生效，默认零开销），","tools/uncovered.py <文件> 按函数列出未覆盖行。","","踩坑记录：第一版判定写成 fn.startswith(PKG)，在 pytest 里一条都收不到；","改成子串 'ai_trader' in fn 才正常。原因没完全坐实，所以现在用更宽松的判定","——宁可多记几个文件，也不要静默地记不到。","","=== 八、剩下的未覆盖重点（未处理） ===","","    _step 485-550 / _manage   剥头皮整条路径      死代码，保留作对照","    _fallback_stop 61-76      持仓缺止损价的兜底   活的，值得补测试","    _open 1089-1093           权益陈旧时禁止开仓   活的风险路径，寄存器","    reconcile_live 部分分支   接管无成本价持仓     实盘才会走到","    _step_trend 684-685       空头方向 best/worst  只做多，不可达","","_open 那条尤其值得下次补：_equity_stale 时禁止开仓是资金安全有关的守卫，","现在没有任何测试碰它。","","=== 九、线上状态 ===","","服务器 /etc/ai-trader/env 里没有 AI_EXEC_MARKET，走默认 spot——","正好是采纳的那一侧，所以行为正确。故意不补这一行：默认值已是安全侧，","改动需要重启服务，零收益带风险。","","账户仍未到账（现货 USDT = 0）。"]''')
meta = json.loads(r'''{"round":100,"theme":"覆盖率审计挖出「拼错就静默换策略」的洞","coverage":{"total":"68.1%","engine":"82%","trend":"81%","spot":"91%","live":"85%","features":"1% (仅剥头皮使用)"},"finding_dead_code":"engine._step 485-550 与 _manage 是剥头皮整条路径，生产从不执行","defect":"os.environ.get 的 default 只在变量未定义时生效；空值/拼错绕过默认值","proof":{"trend":"ok","' Trend '":"scalp","TREND":"scalp","Trand":"scalp","''":"scalp","'trend '":"scalp"},"second_entry":"AI_EXEC_MARKET=Spot -> main.py:73 判非 spot -> 建永续执行器（100U 1x 生死线 77.9U）","why_not_hypothetical":["服务器已有 AI_FEISHU_WEBHOOK= 空值写法","config 注释记载该坑已踩过一次，但只改了默认值"],"fix":"_pick(env, default, allowed)：空值->默认+warning；未知值->ValueError 拒绝启动；大小写/空白归一","regression_caught":"test_deploy_env_completeness 红——扫描器认不出 _pick；扩了正则而非放宽断言，扫到 15 个变量","tests_total":494,"mutation":"5/5 红（含还原原始 bug 时 7 条全红）","uncovered_left":["_fallback_stop 61-76 (活的)","_open 1089-1093 _equity_stale (寄存器)","reconcile_live 接管分支","_step_trend 684-685 空头（不可达）"],"server_env_note":"服务器无 AI_EXEC_MARKET，走默认 spot（安全侧），故意不补","account_state":{"spot_usdt":0}}''')
J = Journal('data/market_trade.db')
J.start()
J.add('info', u'覆盖率审计挖出「拼错就静默换策略」的洞：AI_STRATEGY=空/Trand 会掉进剥头皮分支',
      chr(10).join(L), json.dumps(meta, ensure_ascii=False))
print('journal ok')
J.stop()